$t['Check your payment setup before accepting payments. No charges or subscriptions are created by these checks.'] = 'Ödeme kabul etmeden önce ödeme kurulumunuzu kontrol edin. Bu kontroller herhangi bir ücret veya abonelik oluşturmaz.';
$t['Check your PayPal setup before accepting payments. These checks only authenticate and read: no payment, plan, agreement, payout or refund is created, and no webhook is deleted.'] = 'Ödeme kabul etmeden önce PayPal kurulumunuzu kontrol edin. Bu kontroller yalnızca kimlik doğrular ve okuma yapar: hiçbir ödeme, plan, sözleşme, para aktarımı veya iade oluşturulmaz ve hiçbir webhook silinmez.';
