$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Hedefle bağlantı yayın sırasında koptu. Bu geçici bir ağ sorunu olabilir; FFMPEG yeniden bağlanmayı deneyecek.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'YouTube bağlantısı kesildi. Yükleme duraklatıldı ve devam ettirilebilir.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Bağlantı kesildi. Bu aboneliği yeniden denemeden önce hesabınızı kontrol edin.';
$t['The connection was renewed.'] = 'Bağlantı yenilendi.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Yetkilendirme tamamlanmadan bağlantı penceresi kapatıldı. Hiçbir hesap bağlanmadı.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Dönüştürülen dosyalar saklandı. Aktarımı yeniden denemek için site yöneticisiyle iletişime geçin; videoyu tekrar yüklemeniz gerekmez.';
$t['The converted video could not be sent back to this site.'] = 'Dönüştürülen video bu siteye geri gönderilemedi.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Seçilen kartın müşterileri. Arayın, sıralayın, e-postaları kopyalayın veya her şeyi bir elektronik tabloya aktarın.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Bu web sitesinin günlük YouTube yükleme kotasına ulaşıldı. Yüklemeler Pasifik Saati ile gece yarısından sonra yeniden kullanılabilir olur. Lütfen daha sonra tekrar deneyin.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Veritabanı sürümü yalnızca bir veritabanı geçişi uygulandığında değişir. Sürüm etiketi veya commit ile eşleşmesi beklenmez.';
$t['The default'] = 'Varsayılan';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Hedef RTMP sunucusu bağlantıyı reddetti. Yayın URL\'sini kontrol edin ve sunucunun çevrimiçi olduğundan emin olun.';
