$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Hedef sunucu 403 döndürdü. Yayın anahtarı geçersiz veya süresi dolmuş olabilir.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Hedef video kaldırıldı veya bu hesap onu düzenleyemiyor. Sitedeki video ve hesap erişimini kontrol edin.';
