$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Giriş akışı geçersiz veri içeriyor. Kaynak HLS henüz hazır olmayabilir veya yayın kesilmiş olabilir.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Yüklü PHP paketi her iki düzeltmeyi de listeliyor, ancak bu web işlemi hâlâ güncellemeden önce yüklenen kopyayı çalıştırıyor. Apache veya PHP-FPM\'i yeniden başlatın.';
