$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Henüz İzle Başına Öde planı yok. Pay-Per-View eklentisinin PPV Planları sekmesinde bir tane oluşturun.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Henüz video içerebilecek bir plan yok. PPV Planları sekmesinde bir tane oluşturun, ardından buraya geri dönün.';
$t['There is no streaming now'] = 'Şu anda Canlı Yayın yok';
