$t['The request to the social network failed. Please try again later.'] = 'Sosyal ağa yapılan istek başarısız oldu. Lütfen daha sonra tekrar deneyin.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Restreamer sunucusu hedefe ulaşamıyor. Ağ bağlantısını kontrol edin.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Sorun devam ettiği sürece aynı uyarı en fazla %s bir tekrarlanır.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Sorun devam ettiği sürece aynı uyarı en fazla birkaç saatte bir tekrarlanır.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Seçilen kamera veya mikrofon kullanılamıyor. Lütfen başka bir cihaz seçin.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Seçilen konum gerçek bir sayfada vurgulanır. Mobil önizleme yalnızca reklam konumlarını değiştirir; sayfanın geri kalanı tarayıcınızın cihazını kullanır.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Seçilen konum, sitenizin gerçek bir sayfasında çerçeveyle gösterilir ve aşağıda seçtiğiniz konumu takip eder. Mobil önizleme yalnızca reklam konumlarını değiştirir; sayfanın geri kalanı tarayıcınızın cihazını kullanır.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Site, bir veritabanı sorunu nedeniyle şu anda çevrimdışı. Sorunu en kısa sürede çözmek için çalışıyoruz.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Sunucunun diski dolu olduğundan site geçici olarak kullanılamıyor. Bu sorun üzerinde çalışıyoruz ve kısa süre içinde geri döneceğiz.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Sunucunun diski kapasitesine yaklaştığı için site bakımda. Sorunu gideriyoruz ve kısa süre içinde geri döneceğiz.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Site erişimi reddetti. Kodlayıcı hesabının erişimini yenileyin ve yükleme izinlerini kontrol edin.';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Kaynak yayın sona erdi. Canlı yayın bilerek durdurulduysa bu normaldir.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Bölme açık: masaüstü ziyaretçiler artık bu banner\'ı görmüyor, sol ve sağ yarıları görüyorlar.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Yayında zaman damgası kesintileri var. Bu, hedef platformda arabelleğe alma veya oynatma sorunlarına neden olabilir.';
