$t['Your wallet balance already covers this purchase. Reload the page and pay with your balance; no Bitcoin payment is needed.'] = 'Cüzdan bakiyeniz bu satın alımı zaten karşılıyor. Sayfayı yeniden yükleyip bakiyenizle ödeyin; Bitcoin ödemesine gerek yok.';
$t['Your wallet balance already covers this purchase. Reload the page and pay with your balance; no PayPal payment is needed.'] = 'Cüzdan bakiyeniz bu satın alımı zaten karşılıyor. Sayfayı yeniden yükleyip bakiyenizle ödeyin; PayPal ödemesine gerek yok.';
$t['Your wallet balance is %s. This purchase uses %s from your wallet.'] = 'Cüzdan bakiyeniz %s. Bu satın alım cüzdanınızdan %s kullanır.';
$t['Your webhook endpoint should respond with HTTP 200 status code for successful processing. The request timeout is 1 second, so ensure your endpoint responds quickly.'] = 'Webhook uç noktanız başarılı işlem için HTTP 200 durum koduyla yanıt vermelidir. İstek zaman aşımı 1 saniyedir, bu nedenle uç noktanızın hızlı yanıt verdiğinden emin olun.';
$t['Your Webhook Secret Key:'] = 'Webhook Gizli Anahtarınız:';
$t['Your YouTube authorization expired or was revoked. Reconnect your YouTube account and try again.'] = 'YouTube yetkilendirmenizin süresi doldu veya iptal edildi. YouTube hesabınızı yeniden bağlayıp tekrar deneyin.';
$t['Your YouTube channel reached its daily upload limit. Please try again in 24 hours.'] = 'YouTube kanalınız günlük yükleme sınırına ulaştı. Lütfen 24 saat sonra tekrar deneyin.';
$t['YouTube'] = 'YouTube';
$t['youtube-dl uses Python and some servers do not come with python by default. To install Python type:'] = 'youtube-dl uses Python and some servers do not come with python by default. To install Python type:';
$t['YouTube: Google only lists channels you own or manage as a Brand Account. If your channel is not listed, fill in its stream URL and stream key by hand in the form.'] = 'YouTube: Google yalnızca sahibi olduğunuz veya Marka Hesabı olarak yönettiğiniz kanalları listeler. Kanalınız listede yoksa yayın URL\'sini ve yayın anahtarını formda elle girin.';
$t['YouTube accepts up to 100 characters.'] = 'YouTube en fazla 100 karakter kabul eder.';
$t['YouTube accepts up to 5000 characters. HTML is removed.'] = 'YouTube en fazla 5000 karakter kabul eder. HTML kaldırılır.';
$t['YouTube and other supported video links download through your own connection, which can help when a provider blocks the Encoder server.'] = 'YouTube ve desteklenen diğer video bağlantıları kendi bağlantınız üzerinden indirilir; bu, bir sağlayıcı Encoder sunucusunu engellediğinde yardımcı olabilir.';
$t['YouTube category'] = 'YouTube kategorisi';
$t['YouTube could not process the uploaded file. Check that the video plays correctly on this site and publish it again.'] = 'YouTube yüklenen dosyayı işleyemedi. Videonun bu sitede doğru oynatıldığını kontrol edip yeniden yayınlayın.';
$t['YouTube Data API'] = 'YouTube Data API';
$t['YouTube Data API Overview'] = 'YouTube Data API Overview';
$t['YouTube did not accept the description. Edit the description and publish again.'] = 'YouTube açıklamayı kabul etmedi. Açıklamayı düzenleyip yeniden yayınlayın.';
$t['YouTube did not accept the selected category. Choose another category and publish again.'] = 'YouTube seçilen kategoriyi kabul etmedi. Başka bir kategori seçip yeniden yayınlayın.';
$t['YouTube did not accept the selected privacy setting. Choose another one and publish again.'] = 'YouTube seçilen gizlilik ayarını kabul etmedi. Başka bir ayar seçip yeniden yayınlayın.';
$t['YouTube did not accept the tags. Edit the tags and publish again.'] = 'YouTube etiketleri kabul etmedi. Etiketleri düzenleyip yeniden yayınlayın.';
$t['YouTube did not accept the title. Edit the title and publish again.'] = 'YouTube başlığı kabul etmedi. Başlığı düzenleyip yeniden yayınlayın.';
$t['YouTube did not accept the video details. Check the title, description and tags, then publish again.'] = 'YouTube video ayrıntılarını kabul etmedi. Başlığı, açıklamayı ve etiketleri kontrol edip yeniden yayınlayın.';
$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'YouTube bu yüklemeye izin vermedi. YouTube hesabınızı yeniden bağlayın ve bu web sitesinin YouTube videolarınızı yönetmesine izin verin.';
$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = 'YouTube şu anda çok fazla istek alıyor. Lütfen birkaç dakika bekleyip tekrar deneyin.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'YouTube, politikalarına uymadığı için videoyu reddetti.';
$t['YouTube rejected the video because it is a duplicate of a video already on your channel.'] = 'YouTube, kanalınızda zaten bulunan bir videonun kopyası olduğu için videoyu reddetti.';
$t['YouTube rejected the video because it is longer than your channel allows. Verify your YouTube account to upload longer videos.'] = 'YouTube, videonun kanalınızın izin verdiğinden uzun olması nedeniyle videoyu reddetti. Daha uzun videolar yüklemek için YouTube hesabınızı doğrulayın.';
$t['YouTube rejected the video because of a copyright claim.'] = 'YouTube, bir telif hakkı talebi nedeniyle videoyu reddetti.';
$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'YouTube beklenmeyen bir hata döndürdü. Lütfen daha sonra tekrar deneyin. Sorun devam ederse site yöneticisiyle iletişime geçin.';
$t['YouTube URL'] = 'YouTube URL\'si';
